// The bindings are only used by the tests, so non-test builds see them as dead.
#[allow(dead_code)]
mod sys {
    // The bindings generated by `build.rs` (see `OUT_DIR`), which make `bm_add`
    // visible to the tests below.
    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}

#[cfg(test)]
mod tests {
    use super::sys::bm_add;

    #[test]
    fn test_add() {
        assert_eq!(unsafe { bm_add(2, 3) }, 5);
        assert_eq!(unsafe { bm_add(0, 0) }, 0);
    }
}
